                            case Kind.Utf16String:
                                valueBuilder.AddProperty(name, _utf16Backing);
                                break;
                            default:
                                Debug.Fail("Unexpected Kind");
                                break;
                        }
                    }

                    internal void AddAsProperty(string name, ref ComplexValueBuilder valueBuilder)
                    {
                        switch(_kind)
                        {
                            case Kind.Unknown:
                                break;
                            case Kind.JsonElement:
                                valueBuilder.AddProperty(name, _jsonElement);
                                break;
                            case Kind.RawUtf8StringRequiresUnescaping:
                                valueBuilder.AddPropertyRawString(name, _utf8Backing, valueRequiresUnescaping: true);
                                break;
                            case Kind.RawUtf8StringNotRequiresUnescaping:
                                valueBuilder.AddPropertyRawString(name, _utf8Backing, valueRequiresUnescaping: false);
                                break;
                            case Kind.Utf8String:
                                valueBuilder.AddProperty(name, _utf8Backing, escapeValue: true, valueRequiresUnescaping: false);
                                break;
                            case Kind.Utf16String:
                                valueBuilder.AddProperty(name, _utf16Backing);
                                break;
                            default:
                                Debug.Fail("Unexpected Kind");
                                break;
                        }
                    }

                    internal void AddAsItem(ref ComplexValueBuilder valueBuilder)
                    {
                        switch(_kind)
                        {
                            case Kind.Unknown:
                                break;
                            case Kind.JsonElement:
                                valueBuilder.AddItem(_jsonElement);
                                break;
                            case Kind.RawUtf8StringRequiresUnescaping:
                                valueBuilder.AddItem(_utf8Backing, escapeValue: false, requiresUnescaping: true);
                                break;
                            case Kind.RawUtf8StringNotRequiresUnescaping:
                                valueBuilder.AddItem(_utf8Backing, escapeValue: false, requiresUnescaping: false);
                                break;
                            case Kind.Utf8String:
                                valueBuilder.AddItem(_utf8Backing, escapeValue: true, requiresUnescaping: false);
                                break;
                            case Kind.Utf16String:
                                valueBuilder.AddItem(_utf16Backing);
                                break;
                            default:
                                Debug.Fail("Unexpected Kind");
                                break;
                        }
                    }
                }

                /// <summary>
                /// Creates and initializes a mutable document from a value.
                /// </summary>
                /// <param name="workspace">The JSON workspace.</param>
                /// <param name="value">The value with which to initialize the builder.</param>
                /// <param name="initialCapacity">The (optional) estimate of the capacity to reserve for the document.</param>
                /// <returns>An instance of a mutable document initialized with the given value.</returns>
                public static JsonDocumentBuilder<Mutable> CreateBuilder(
                    JsonWorkspace workspace, scoped in Source value, int initialCapacity = 1)
                {
                    // Create the document builder without a MetadataDb
                    JsonDocumentBuilder<Mutable> documentBuilder = workspace.CreateBuilder<Mutable>(-1);
                    ComplexValueBuilder cvb = ComplexValueBuilder.Create(documentBuilder, initialCapacity);
                    value.AddAsItem(ref cvb);
                    Debug.Assert(cvb.MemberCount == 1);
                    ((IMutableJsonDocument)documentBuilder).SetAndDispose(ref cvb);
                    return documentBuilder;
                }

                /// <inheritdoc cref="global::Corvus.Text.Json.JsonElement.CreateBuilder(JsonWorkspace)"/>
                public JsonDocumentBuilder<Mutable> CreateBuilder(JsonWorkspace workspace)
                {
                    return workspace.CreateBuilder<WhatPackageManagerToUse, Mutable>(this);
                }

                /// <summary>
                /// Creates a new <see cref="ParsedJsonDocument{T}"/> from a value.
                /// </summary>
                /// <param name="value">The value with which to initialize the document.</param>
                /// <param name="initialCapacity">The (optional) estimate of the capacity to reserve for the document.</param>
                /// <returns>A <see cref="ParsedJsonDocument{T}"/> containing the given value. The caller must dispose it.</returns>
                public static ParsedJsonDocument<WhatPackageManagerToUse> Create(
                    scoped in Source value, int initialCapacity = 1)
                {
                    ParsedJsonDocumentBuilder documentBuilder = ParsedJsonDocumentBuilder.Rent();
                    try
                    {
                        ComplexValueBuilder cvb = ComplexValueBuilder.Create(documentBuilder, initialCapacity);
                        value.AddAsItem(ref cvb);
                        Debug.Assert(cvb.MemberCount == 1);
                        ((IMutableJsonDocument)documentBuilder).SetAndDispose(ref cvb);
                        return documentBuilder.ToParsedJsonDocument<WhatPackageManagerToUse>();
                    }
                    finally
                    {
                        documentBuilder.Dispose();
                    }
                }
            }
        }
    }
}
